    "rutOrganismo": "61.608.204-3",
    "tipoOficial": "LP",
    "tipoNombre": "Licitación Pública >100 UTM",
    "titulo": "DGC - SUMINISTRO DE CARTUCHOS PARA SISTEMA DE ANÁLISIS DE TECNICAS VISCOELASTICA CON EQUIPO ASOCIADO",
    "organismo": "SERVICIO DE SALUD OCCIDENTE HOSPITAL SAN JUAN DE DIOS",
